initial_condition:
with {
   the SUT containing an initial state
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Delete Context Source Registration Subscription with Response Status Code set to 404     and
        Delete Context Source Registration Subscription with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound'     and
        Delete Context Source Registration Subscription with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceSubscriptions/{subscription_id}'
        method set to 'DELETE'
        Delete Context Source Registration Subscription with id set to 'urn:ngsi-ld:Subscription:unknowSubscription'
}
